    local t = CfUtils.GetIdGroupData(AutoIds.IdSetting1101, key)
    return t
end

---IsHaveWaveData  判断是否有这个波次的信息
---@param key string
---@return boolean
function BambooUtils.IsHaveWaveData(key)
    local tableFile = SettingMgr:GetInstance():Get(string.format("%sIDGroup", AutoIds.IdSetting1101))
    local all = {}
    for k, v in pairs(tableFile) do
        table.insert(all, v:Get("type"))
    end

    for k, v in pairs(all) do
        if checkString(v) == checkString(key) then
            return true
        end
    end
    return false
end

