---IsGrideHasEvent 格子是否有事件
---@param grideVo BambooMapPointVo
---@return boolean
function BambooUtils.IsGrideHasEvent(grideVo)
    local vo = BambooUtils.GetEventVoByGride(grideVo)
    if not vo then 
        return false
    end
    --是弹窗
    if checkNumber(vo.type) == ConstantsBamboo.GrideEventType.Tips then
        --模型没了表示这个事件没了
        if isNull(grideVo._grideModelGo) then
            return false
        end
    end
    return checkNumber(vo.type) ~= ConstantsBamboo.GrideEventType.None and checkNumber(vo.type) ~= ConstantsBamboo.GrideEventType.Birth
end

