---GetEventEffects 获取一个事件所有的效果
---@param eventId number @ 效果id
---@return string[]
function BambooUtils.GetEventEffects(eventId)
    eventId = checkNumber(eventId)
    if eventId <= 0 then
        return nil
    end

    local t = {}
    local effectGroupIds = BambooUtils.GetEventEffectIds(eventId)
    if effectGroupIds and table.count(effectGroupIds) then
        for k, v in pairs(effectGroupIds) do
            local effectIds = BambooUtils.GetEffects(v)
            if effectIds then
                for _, id in pairs(effectIds) do
                    table.insert(t, id)
                end
            end
        end
    end
    return t
end

