---GetCurChallengeLevel 获取当前章节应该挑战的等级
---@param chapterId integer @ 关卡id
---@return integer
function BambooUtils.GetCurChallengeLevel(chapterId)
    local t = BambooUtils.GetChallengeQuests(chapterId)
    if not t then
        return 0
    end
    local newQuestId = BambooUtils.GetNewQuestId(chapterId)
    if newQuestId > 0 then
        ---@type QuestBambooChallengeVo
        local vo = QuestConfMgr:GetInstance():GetQuestVoById(newQuestId)
        if not vo then
            return 0
        end
        if checkNumber(vo.regionLevel) >= table.count(t) then
            return checkNumber(vo.regionLevel)
        else
            return checkNumber(vo.regionLevel) + 1
        end
    else
        return checkNumber(t[1])
    end
    return 0
end

---IsUnlockChallengeChapter 是否解锁了章节
---@param chapterId integer @ 章节id
---@return boolean, string
function BambooUtils.IsUnlockChallengeChapter(chapterId)
    chapterId = checkNumber(chapterId)
    if chapterId <= 0 then
        return false
    end

    local vo = BambooUtils.GetQuestBambooChallengeChapterVo(chapterId)
    if not vo then
        return false
    end

    --空字符串
    if string.isEmpty(vo.unlockChapter) then
        return true
    end

    local t = CfUtils.Split(vo.unlockChapter)
    if not t then
        return false
    end

    for k, v in pairs(t) do
        local isUnlock = BambooUtils.IsPassMap(v)
        if not isUnlock then 
            return false, vo.unlockDesc
        end
    end

    return true, vo.unlockDesc
end

---IsUnlockChallengeQuest 是否解锁了挑战关卡
---@param questId integer @ 关卡id
---@return boolean, string
function BambooUtils.IsUnlockChallengeQuest(questId)
    questId = checkNumber(questId)
    if questId < 0 then
        return false
    end
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
    if not vo then
        return false
    end

    local newQuestId = BambooUtils.GetNewQuestId(vo.type)

    if newQuestId < checkNumber(vo.unlockNum) then
        local unlockVo = QuestConfMgr:GetInstance():GetQuestVoById(vo.unlockNum)
        return false, localize("通关_num_解锁", {_num_ = unlockVo.label})
    elseif not GameUtils.IsUnlockedSingle(Constants.CommonUnlockType.PlayerLevel, checkString(vo.level)) then
        return false, localize("等级达到_num_解锁", {_num_ = vo.level})
    end
    return true
end

---IsPassChallengeQuest 是否通关了挑战关卡
---@param questId integer @ 关卡id
---@return boolean
function BambooUtils.IsPassChallengeQuest(questId)
    questId = checkNumber(questId)
    if questId < 0 then
        return false
    end

    local vo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
    if not vo then
        return false
    end

    local newQuestId = BambooUtils.GetNewQuestId(vo.type)
    return newQuestId >= questId
end

