---IsUnlockMap 是否解锁了该地图
---@param mapId integer @ 地图id
---@param activityUuid integer
---@return boolean, string
function BambooUtils.IsUnlockMap(mapId, activityUuid)
    activityUuid = checkNumber(activityUuid)
    if activityUuid <= 0 then
        return false, localize("activityUuid 错误")
    end 
    local openDay = BambooUtils.GetActivityOpenDay(activityUuid)

    local vo = BambooUtils.GetBambooActivityCopyVo(mapId)
    if not vo then
        return false, localize("配置错误， 没有该点")
    elseif openDay < checkNumber(vo.unlockDay) then
        return false, localize("活动开始第_num_天解锁", {_num_ = vo.unlockDay})
    else
        local isUnlockMap = false
        local t = CfUtils.Split(vo.unlockChapter)
        if not t or table.count(t) <= 0 then
            isUnlockMap = true
        else
            isUnlockMap = true
            for k, v in pairs(t) do
                if not BambooUtils.IsPassMap(v) then
                    isUnlockMap = false
                    break
                end
            end
        end

        if isUnlockMap then
            t = CfUtils.Split(vo.specialUnlockParam)
            if t and table.count(t) > 0 then
                local isUnlockSpecial = false
                for k, v in pairs(t) do
                    if BambooUtils.IsCompleteSpecialEvent(v) then
                        return true
                    end
                end
                return false, vo.tips--localize("未完成前置事件")
            end
        else
            return false, vo.tips --localize("请先通关前置关卡")
        end
    end

    return true
end

---IsUnlockMapEvent 是否解锁了一个事件
---@param eventId integer @ 事件id
---@param activityUuid integer
---@return boolean, string
function BambooUtils.IsUnlockMapEvent(eventId, activityUuid)
    local eventVo = BambooUtils.GetBambooEventVo(eventId)
    if not eventVo then
        return false
    end

    local t = CfUtils.Split(eventVo.unlockNode)
    if not t or table.count(t) <=0 then
        return true
    end
    for k, v in pairs(t) do 
        if not BambooUtils.IsCompleteSpecialEvent(v) then
            return false, eventVo.unlockDesc
        end
    end 
    return true
end

