---GetAllUnlockMapId 获取所有解锁的地图id
---@param activityUuid integer 
---@return integer[]
function BambooUtils.GetAllUnlockMapId(activityUuid)
    if checkNumber(activityUuid) == 0 then
        return {}
    end
    local activityId = BambooUtils.GetActivityId(activityUuid)
    if checkNumber(activityId) == 0 then
        return {}
    end

    local t = BambooUtils.GetBamBooAllMapCopy(activityId)
    if not t then
        return {}
    end
    local _t = {}
    for k, v in pairs(t) do
        if BambooUtils.IsUnlockMap(v, activityUuid) then
            table.insert(_t, v)
        end
    end
    return _t
end

---IsCanBattle 是否可以进入战斗
---@param activityUuid integer
---@return boolean
function BambooUtils.IsCanBattle(activityUuid)
    if checkNumber(activityUuid) == 0 then
        return false
    end
    local activityId = BambooUtils.GetActivityId(activityUuid)
    if checkNumber(activityId) == 0 then
        return false
    end
    ---@type BambooQuestComponent
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.BambooQuestComponent)
    local t = comp:GetAllRole()
    if not t then
        return false
    end
    for k, v in pairs(t) do
        if checkNumber(v.hpPercent) > 0 then
            return true
        end
    end
    return false
end

---GetLockCompare 解锁对照表
---@param activityUuid integer
---@return table[]
function BambooUtils.GetLockCompare(activityUuid)
    local activityId = BambooUtils.GetActivityId(activityUuid)
    if checkNumber(activityId) == 0 then
        return {}
    end 
    local t = BambooUtils.GetBamBooAllMapCopy(activityId)
    if not t or table.count(t) <= 0 then
        return {}
    end

    local _t = {}
    for k, v in pairs(t) do
        local vo = BambooUtils.GetBambooActivityCopyVo(v)
        if vo then
            local lockIds = CfUtils.Split(vo.unlockChapter)
            if lockIds then
                for _, lockId in pairs(lockIds) do
                    table.insert(_t, {
                        lockId = checkNumber(lockId),      
                        targetId = checkNumber(vo.id),      
                    })     
                end
            end
        end
    end
    return _t
end

