---GetFloorPath 地板路径
---@param mapId integer @ 地图id
---@return string
function BambooUtils.GetFloorPath(mapId)
    local vo = BambooUtils.GetBambooActivityCopyVo(mapId)
    if not vo then
        return nil
    end
    return string.format("Scenes/Scene_01_A_25/prefab/pt_regionmap_%s.prefab", vo.SceneId)
end

---GetFloorBgPath 获取地图背景
---@param mapId integer @ 地图id
---@return string
function BambooUtils.GetFloorBgPath(mapId)
    local vo = BambooUtils.GetBambooActivityCopyVo(mapId)
    if not vo then
        return nil
    end
    return vo.bgImage
end

function BambooUtils.GetConfigParamsById(id)
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting6261,"BambooParamsVo",id)
    if vo == nil then
        printError("PT活动参数表 中未找到 %s", id)
        return 0
    end
    return vo.num
end

return BambooUtils
